Core Domain Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(core_domain_service, "Core Domain Service") {
    Component(CatalogManagementComponent, "Catalog Management Component", "Spring MVC/Data", "Handling physical and digital items.")
    Component(CirculationFinesComponent, "Circulation & Fines Component", "Spring Boot", "Manages loans, returns, and payment processing.")
    Component(EventPublisherComponent, "Event Publisher Component", "Spring AMQP", "Dispatching domain events.")
    Component(RegistryIntegrationComponent, "Registry Integration Component", "Spring Cloud OpenFeign", "Synchronizing metadata.")
    Component(SecurityContextAuthComponent, "Security Context & Auth Component", "Spring Security", "Validating tokens locally.")
}

Rel(CatalogManagementComponent, CirculationFinesComponent, "Interacts with")
Rel(EventPublisherComponent, RegistryIntegrationComponent, "Coordinates with")
@enduml

Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(Database, "Database") {
    Component(Primary_PostgreSQL_Instance, "Primary PostgreSQL Instance", "PostgreSQL", "Primary relational OLTP data management system ensuring strict EU-only data residency.")
    Component(PostgreSQL_Read_Replicas, "PostgreSQL Read Replicas", "PostgreSQL", "Read replicas providing optimized read performance for catalogue searches.")
    Component(PgBouncer_Connection_Pooler, "PgBouncer Connection Pooler", "PgBouncer", "Manages and pools database connections efficiently under high concurrency.")
    Component(Audit_Logging_Subsystem, "Audit Logging Subsystem", "pgAudit", "Provides native audit logging to ensure strict EU data governance compliance.")
    Component(Fuzzy_Text_Search_Extension, "Fuzzy-Text Search Extension", "pg_trgm Extension", "Enabled in PostgreSQL to support fast fuzzy-text searches and meet performance requirements.")
}

Rel(PgBouncer_Connection_Pooler, Primary_PostgreSQL_Instance, "Routes write queries and transactions", "PostgreSQL Native Protocol over TLS")
Rel(PgBouncer_Connection_Pooler, PostgreSQL_Read_Replicas, "Routes read queries", "PostgreSQL Native Protocol over TLS")
@enduml

Message Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(message_broker, "Message Broker") {
    Component(ExchangeComponent, "Exchange Component", "RabbitMQ Exchange", "Routes incoming messages from the Core Domain Service to appropriate queues.")
    Component(notification_queue, "notification-queue", "RabbitMQ Queue", "Queues notification tasks for asynchronous processing by the Notification Worker.")
    Component(audit_event_queue, "audit-event-queue", "RabbitMQ Queue", "Stores audit event messages to maintain compliance and activity logs.")
    Component(DataPolicyEnforcementComponent, "Data Policy Enforcement Component", "RabbitMQ Policy Engine", "Enforces EU-only data residency and local storage policies.")
}

Rel(ExchangeComponent, notification_queue, "Routes notification messages", "AMQP")
Rel(ExchangeComponent, audit_event_queue, "Routes audit messages", "AMQP")

@enduml
